const body = $json.body || $json;
const operacao = typeof body.operacao === 'string' ? body.operacao.trim() : '';
const idEmpresa = typeof body.idEmpresa === 'string' ? body.idEmpresa.trim() : '';
const requestId = (typeof body.requestId === 'string' && body.requestId.trim().length > 0)
  ? body.requestId.trim()
  : ('sem-request-id-' + Date.now());
const dados = (body.dados && typeof body.dados === 'object') ? body.dados : {};

// Seis operações reconhecidas nesta fase (read-only) — qualquer outra vira
// INVALID_OPERATION. Não criar branches vazios de Financeiro/Comunicação/IA aqui
// (ver sticky note desta workflow): adicionar a próxima operação exige voltar a
// este array E ao fluxo real.
const OPERACOES_SUPORTADAS = ['clientes.listar', 'servicos.listar', 'profissionais.listar', 'empresa.obter', 'disponibilidades.listar', 'agendamentos.listar'];

let erro_codigo = '';
let erro_mensagem = '';

if (!operacao) {
  erro_codigo = 'VALIDATION_ERROR';
  erro_mensagem = 'operacao é obrigatória.';
} else if (!idEmpresa) {
  erro_codigo = 'TENANT_REQUIRED';
  erro_mensagem = 'idEmpresa é obrigatório.';
} else if (!OPERACOES_SUPORTADAS.includes(operacao)) {
  erro_codigo = 'INVALID_OPERATION';
  erro_mensagem = 'Operação "' + operacao + '" não é reconhecida pelo APP-WF019.';
}

return [{ json: { operacao, idEmpresa, requestId, dados, erro_codigo, erro_mensagem } }];

// CLIENTES sozinha não tem "próximo atendimento" nem totais de atendimento/gasto
// (dependeriam de AGENDAMENTOS/PAGAMENTOS, fora do escopo desta Fase 1) — por isso o
// shape de integração devolvido aqui não inclui esses campos; o NestJS os preenche com
// um valor neutro documentado (ver clientes.service.ts, toClienteFromIntegracao).
// Nunca inclui ID_EMPRESA nem colunas técnicas do Sheets.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

// alwaysOutputData garante um item mesmo quando a busca é 0 linhas legitimamente — esse
// placeholder não tem ID_CLIENTE, então é descartado aqui (não vira um cliente falso).
const clientes = linhas
  .filter((row) => row && row.ID_CLIENTE)
  .map((row) => ({
    idCliente: String(row.ID_CLIENTE),
    nome: row.NOME || '',
    telefone: row.TELEFONE || '',
    email: row.EMAIL || null,
    dataNascimento: row.DATA_NASCIMENTO || null,
    status: row.STATUS === 'INATIVO' ? 'INATIVO' : 'ATIVO',
    clienteDesde: row.DATA_CADASTRO ? String(row.DATA_CADASTRO).slice(0, 10) : null,
    ultimoAtendimento: row.ULTIMO_ATENDIMENTO ? String(row.ULTIMO_ATENDIMENTO).slice(0, 10) : null,
    observacoes: row.OBSERVACOES || null,
  }));

return [{ json: { clientes, requestId } }];

// SERVICOS: schema real confirmado (corrigido nesta tarefa) — ID_SERVICO, ID_EMPRESA,
// NOME, CATEGORIA, DESCRICAO, DURACAO_MIN, TEMPO_INTERVALO_MIN, VALOR, STATUS,
// DATA_CADASTRO, ULTIMA_ATUALIZACAO. DESCRICAO EXISTE na aba real (premissa anterior de
// que não existia estava errada) e agora é mapeada. CATEGORIA, TEMPO_INTERVALO_MIN,
// DATA_CADASTRO e ULTIMA_ATUALIZACAO existem na fonte mas NÃO fazem parte do contrato
// público `Servico` — deliberadamente nunca lidas/mapeadas aqui (decisão de escopo, não
// erro: adicioná-las ao contrato é decisão de produto fora desta tarefa). Nunca inclui
// ID_EMPRESA nem colunas técnicas do Sheets.
//
// Hardening (v1.3): ID_SERVICO, NOME, STATUS, DURACAO_MIN e VALOR são obrigatórios.
// STATUS só aceita exatamente 'ATIVO'/'INATIVO' (trim+uppercase, nunca outro valor vira
// 'ATIVO' por default — isso mascararia dado corrompido da fonte). Se QUALQUER serviço
// real da empresa tiver um desses campos inválido, a operação INTEIRA falha com
// UPSTREAM_ERROR — nunca devolve uma lista parcial silenciosamente incompleta.
//
// Hardening (v1.4): distingue o placeholder LEGÍTIMO do alwaysOutputData (item sem
// NENHUM campo operacional de serviço presente — busca realmente vazia) de uma linha
// real corrompida que tem algum campo preenchido mas ID_SERVICO vazio/ausente. O
// segundo caso NUNCA é tratado como "nenhum serviço" — é dado inválido, mesma falha de
// operação inteira das demais validações.
//
// Correção v1.5: DESCRICAO é mapeada (valor preenchido -> string normalizada/trim; vazio
// ou ausente -> null; nunca fabricada, nunca substituída pelo NOME). DESCRICAO é
// OPCIONAL — vazia/ausente nunca falha a operação (diferente de NOME/STATUS/
// DURACAO_MIN/VALOR) — mas conta como "campo operacional presente" na distinção
// placeholder x linha corrompida (v1.4), já que também é um dado real da linha.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

const STATUS_VALIDOS = new Set(['ATIVO', 'INATIVO']);

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function normalizarValorMonetario(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor == null ? '' : valor).trim().replace(/^R\$\s*/i, '');
  if (texto.includes('.') && texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }
  return Number(texto);
}

let existeInvalido = false;
const servicos = [];

for (const row of linhas) {
  if (!row) continue;

  const temIdServico = campoPresente(row.ID_SERVICO);
  const temOutroCampo =
    campoPresente(row.NOME) ||
    campoPresente(row.STATUS) ||
    campoPresente(row.DURACAO_MIN) ||
    campoPresente(row.VALOR) ||
    campoPresente(row.DESCRICAO);

  if (!temIdServico && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente vazia — não é erro, não
    // é um serviço. Ignorado.
    continue;
  }

  if (!temIdServico) {
    // Linha real (tem algum campo operacional preenchido) mas sem ID_SERVICO — dado
    // corrompido da fonte, nunca "nenhum serviço".
    existeInvalido = true;
    continue;
  }

  const nome = typeof row.NOME === 'string' ? row.NOME.trim() : '';
  const status = typeof row.STATUS === 'string' ? row.STATUS.trim().toUpperCase() : '';
  const duracaoMinutos = Number(row.DURACAO_MIN);
  const valor = normalizarValorMonetario(row.VALOR);
  const descricaoBruta = typeof row.DESCRICAO === 'string' ? row.DESCRICAO.trim() : '';
  const descricao = descricaoBruta ? descricaoBruta : null;

  if (
    !nome ||
    !STATUS_VALIDOS.has(status) ||
    !Number.isFinite(duracaoMinutos) ||
    duracaoMinutos < 0 ||
    !Number.isFinite(valor) ||
    valor < 0
  ) {
    existeInvalido = true;
    continue;
  }

  servicos.push({ idServico: String(row.ID_SERVICO), nome, status, duracaoMinutos, valor, descricao });
}

if (existeInvalido) {
  // Mensagem genérica de propósito — nunca expõe qual linha/ID_SERVICO/ID_EMPRESA/
  // planilha está com o dado inválido.
  return [{ json: {
    erro_codigo: 'UPSTREAM_ERROR',
    erro_mensagem: 'Um ou mais serviços cadastrados possuem dados inválidos.',
    requestId,
  } }];
}

return [{ json: { servicos, requestId } }];

// Compartilhado entre clientes.listar e servicos.listar (branches mutuamente
// exclusivos por execução — só um dos dois IFs de erro técnico dispara) — mensagem
// genérica de propósito, não específica de uma fonte.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
return [{ json: {
  erro_codigo: 'UPSTREAM_ERROR',
  erro_mensagem: 'Não foi possível consultar os dados no momento.',
  requestId,
} }];

// Compartilhado entre as seis operações (branches mutuamente exclusivos por
// execução — só um normalizador roda por vez) — lê qualquer um dos campos que o
// normalizador correspondente tiver produzido. `empresa.obter` é a única singular:
// `$json.empresa` já é o objeto direto (nunca um array) quando presente.
return [{ json: { ok: true, data: $json.clientes ?? $json.servicos ?? $json.profissionais ?? $json.disponibilidades ?? $json.agendamentos ?? $json.empresa ?? [], meta: { requestId: $json.requestId } } }];

// Alimentado por múltiplas origens mutuamente exclusivas (envelope inválido, falha
// técnica ao buscar dados, ou dado inválido na fonte de qualquer uma das operações) —
// todas conectadas diretamente na mesma entrada deste node (não um Merge; ver sticky
// note desta workflow para o motivo). Nunca expõe stack, payload bruto do Sheets,
// credencial ou API key — só code/message já decididos antes.
return [{ json: {
  ok: false,
  error: { code: $json.erro_codigo, message: $json.erro_mensagem },
  meta: { requestId: $json.requestId },
} }];

// PROFISSIONAIS: schema real confirmado (correção de schema desta tarefa — a conclusão
// anterior de que só ID_EMPRESA/ID_PROFISSIONAL/NOME/STATUS existiam, baseada em
// workflows que só leem um subconjunto de colunas, estava incompleta) — 12 colunas:
// ID_PROFISSIONAL, ID_EMPRESA, NOME, ESPECIALIDADE, TELEFONE, EMAIL,
// GOOGLE_CALENDAR_ID, DURACAO_INTERVALO_MIN, STATUS, DATA_ADMISSAO, DATA_CADASTRO,
// ULTIMA_ATUALIZACAO. ESPECIALIDADE/TELEFONE/EMAIL EXISTEM de fato e agora são
// mapeadas (trim, vazio/ausente -> null, nunca fabricadas/inferidas por nome ou
// serviço). TELEFONE nunca passa por conversão numérica — é texto/identificador, não
// quantidade (Number() perderia zeros à esquerda, sinal "+" internacional e precisão).
// GOOGLE_CALENDAR_ID (identificador de integração interno), DURACAO_INTERVALO_MIN (uso
// futuro em Agenda/disponibilidade), DATA_ADMISSAO, DATA_CADASTRO e ULTIMA_ATUALIZACAO
// existem na fonte mas NÃO fazem parte do contrato público `Profissional` —
// deliberadamente nunca lidas para o shape de saída (decisão de escopo, não erro).
//
// Hardening (mesmo padrão de CODE - Normalizar Serviços): ID_PROFISSIONAL, NOME e STATUS
// são obrigatórios. STATUS só aceita exatamente 'ATIVO'/'INATIVO' (trim+uppercase, nunca
// outro valor vira 'ATIVO' por default — isso mascararia dado corrompido da fonte).
// ESPECIALIDADE/TELEFONE/EMAIL são opcionais: vazios/ausentes sozinhos nunca falham a
// operação. Se QUALQUER profissional real da empresa tiver ID_PROFISSIONAL/NOME/STATUS
// inválido, a operação INTEIRA falha com UPSTREAM_ERROR — nunca devolve uma lista
// parcial silenciosamente incompleta.
//
// Placeholder x linha corrompida (mesma distinção do hardening de Serviços, revisada
// nesta correção para reconhecer TODAS as colunas reais, não só NOME/STATUS): item sem
// NENHUM campo operacional presente (nem NOME, STATUS, ESPECIALIDADE, TELEFONE, EMAIL,
// GOOGLE_CALENDAR_ID, DURACAO_INTERVALO_MIN, DATA_ADMISSAO, DATA_CADASTRO,
// ULTIMA_ATUALIZACAO) é o placeholder legítimo do alwaysOutputData — busca realmente
// vazia, não um erro. Uma linha real com QUALQUER um desses campos preenchido mas
// ID_PROFISSIONAL ausente é dado corrompido, nunca tratado como "nenhum profissional".
// Um campo com valor `0` válido (ex.: DURACAO_INTERVALO_MIN=0) conta como presente, nunca
// como ausência (ver campoPresente).
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

const STATUS_VALIDOS = new Set(['ATIVO', 'INATIVO']);

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

// Nunca usa Number(): texto normalizado (trim), preservado como string. Vazio/ausente
// vira null — nunca fabricado, nunca inferido de outro campo.
function textoOuNull(valor) {
  if (!campoPresente(valor)) return null;
  const texto = typeof valor === 'string' ? valor : String(valor);
  const aparado = texto.trim();
  return aparado ? aparado : null;
}

let existeInvalido = false;
const profissionais = [];

for (const row of linhas) {
  if (!row) continue;

  const temIdProfissional = campoPresente(row.ID_PROFISSIONAL);
  const temOutroCampo =
    campoPresente(row.NOME) ||
    campoPresente(row.STATUS) ||
    campoPresente(row.ESPECIALIDADE) ||
    campoPresente(row.TELEFONE) ||
    campoPresente(row.EMAIL) ||
    campoPresente(row.GOOGLE_CALENDAR_ID) ||
    campoPresente(row.DURACAO_INTERVALO_MIN) ||
    campoPresente(row.DATA_ADMISSAO) ||
    campoPresente(row.DATA_CADASTRO) ||
    campoPresente(row.ULTIMA_ATUALIZACAO);

  if (!temIdProfissional && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente vazia — não é erro, não
    // é um profissional. Ignorado.
    continue;
  }

  if (!temIdProfissional) {
    // Linha real (tem algum campo operacional preenchido) mas sem ID_PROFISSIONAL —
    // dado corrompido da fonte, nunca "nenhum profissional".
    existeInvalido = true;
    continue;
  }

  const nome = textoOuNull(row.NOME) ?? '';
  const status = typeof row.STATUS === 'string' ? row.STATUS.trim().toUpperCase() : '';

  if (!nome || !STATUS_VALIDOS.has(status)) {
    existeInvalido = true;
    continue;
  }

  profissionais.push({
    idProfissional: String(row.ID_PROFISSIONAL),
    nome,
    especialidade: textoOuNull(row.ESPECIALIDADE),
    telefone: textoOuNull(row.TELEFONE),
    email: textoOuNull(row.EMAIL),
    status,
  });
}

if (existeInvalido) {
  // Mensagem genérica de propósito — nunca expõe qual linha/ID_PROFISSIONAL/ID_EMPRESA/
  // planilha está com o dado inválido.
  return [{ json: {
    erro_codigo: 'UPSTREAM_ERROR',
    erro_mensagem: 'Um ou mais profissionais cadastrados possuem dados inválidos.',
    requestId,
  } }];
}

return [{ json: { profissionais, requestId } }];

// EMPRESAS: schema real confirmado (correção de schema — a conclusão anterior de que só
// 4 colunas existiam, inferida indiretamente dos workflows WF001-018, estava
// incompleta) — 18 colunas: ID_EMPRESA, NOME, CNPJ, TELEFONE, EMAIL, ENDERECO, CIDADE,
// UF, CEP, TIMEZONE, HORARIO_FUNCIONAMENTO, TEMPO_CANCELAMENTO_MIN,
// WHATSAPP_PHONE_NUMBER_ID, WHATSAPP_WABA_ID, GOOGLE_CALENDAR_ID, STATUS, DATA_CADASTRO,
// ULTIMA_ATUALIZACAO.
//
// NOME/TELEFONE/EMAIL EXISTEM de fato e agora alimentam o contrato público com dado
// real (trim; TELEFONE/EMAIL vazio/ausente -> null; NOME vazio/ausente -> '' — mesmo
// tipo não-nulo do contrato, nunca um texto fabricado). TELEFONE nunca passa por
// conversão numérica (é texto/identificador, não quantidade).
//
// CNPJ, ENDERECO, CIDADE, UF, CEP, HORARIO_FUNCIONAMENTO (do estabelecimento — conceito
// distinto de DISPONIBILIDADES, que é por profissional), STATUS, DATA_CADASTRO,
// ULTIMA_ATUALIZACAO, WHATSAPP_WABA_ID e GOOGLE_CALENDAR_ID existem na aba real mas NÃO
// fazem parte do contrato público ConfiguracoesEmpresa — decisão de escopo, nunca lidos
// para o shape de saída, mas todos participam da distinção placeholder x linha
// corrompida abaixo. WHATSAPP_PHONE_NUMBER_ID nunca sai como valor — só a
// presença/ausência vira whatsappConfigurado (minimização de dados).
//
// `empresa.obter` é singular: EMPRESAS deveria ter exatamente 1 linha para o idEmpresa
// do tenant já autenticado. Um item realmente vazio do alwaysOutputData (nenhum dos 17
// campos reais presente) é ausência de empresa; uma linha com QUALQUER campo real
// preenchido mas ID_EMPRESA ausente é dado corrompido — para esta operação singular,
// as duas situações convergem para o mesmo resultado (UPSTREAM_ERROR, nunca "sucesso
// vazio"), mas a distinção fica registrada aqui por clareza/auditoria, no mesmo padrão
// das operações .listar. TIMEZONE/TEMPO_CANCELAMENTO_MIN ausentes/inválidos na linha
// real também falham a operação — nunca um default silencioso.
//
// Hardening (último, antes da homologação): o filtro ID_EMPRESA do node Sheets deveria
// garantir no máximo 1 linha real por empresa, mas nunca confiamos cegamente nisso — se
// 2 ou mais linhas reais (com ID_EMPRESA presente) vierem para a mesma chamada, isso é
// duplicidade acidental na fonte. NUNCA escolhemos a primeira, a última, nem mesclamos
// os dados das linhas — a operação INTEIRA falha com UPSTREAM_ERROR (mesma mensagem
// genérica de sempre, nunca expõe ID_EMPRESA/CNPJ/telefone/e-mail/quantas linhas
// existem). Essa checagem tem prioridade sobre "linha corrompida"/"ausência de
// empresa": duplicidade é sempre o motivo relatado quando ocorre junto de outro
// problema.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function textoOuNull(valor) {
  if (!campoPresente(valor)) return null;
  const texto = typeof valor === 'string' ? valor : String(valor);
  const aparado = texto.trim();
  return aparado ? aparado : null;
}

function erroUpstream() {
  return [{ json: {
    erro_codigo: 'UPSTREAM_ERROR',
    erro_mensagem: 'Não foi possível carregar as configurações da empresa.',
    requestId,
  } }];
}

let empresaReal = null;
let existeInvalido = false;
let quantidadeLinhasReais = 0;

for (const row of linhas) {
  if (!row) continue;

  const temIdEmpresa = campoPresente(row.ID_EMPRESA);
  const temOutroCampo =
    campoPresente(row.NOME) ||
    campoPresente(row.CNPJ) ||
    campoPresente(row.TELEFONE) ||
    campoPresente(row.EMAIL) ||
    campoPresente(row.ENDERECO) ||
    campoPresente(row.CIDADE) ||
    campoPresente(row.UF) ||
    campoPresente(row.CEP) ||
    campoPresente(row.TIMEZONE) ||
    campoPresente(row.HORARIO_FUNCIONAMENTO) ||
    campoPresente(row.TEMPO_CANCELAMENTO_MIN) ||
    campoPresente(row.WHATSAPP_PHONE_NUMBER_ID) ||
    campoPresente(row.WHATSAPP_WABA_ID) ||
    campoPresente(row.GOOGLE_CALENDAR_ID) ||
    campoPresente(row.STATUS) ||
    campoPresente(row.DATA_CADASTRO) ||
    campoPresente(row.ULTIMA_ATUALIZACAO);

  if (!temIdEmpresa && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente sem correspondência —
    // não é dado corrompido, é ausência de empresa (tratada abaixo, fora do loop).
    continue;
  }

  if (!temIdEmpresa) {
    // Linha real (tem algum campo operacional preenchido) mas sem ID_EMPRESA — dado
    // corrompido da fonte, nunca tratado como "nenhuma empresa".
    existeInvalido = true;
    continue;
  }

  quantidadeLinhasReais += 1;

  const nome = textoOuNull(row.NOME) ?? '';
  const telefone = textoOuNull(row.TELEFONE);
  const email = textoOuNull(row.EMAIL);
  const timezone = typeof row.TIMEZONE === 'string' ? row.TIMEZONE.trim() : '';
  const tempoCancelamentoMinutos = Number(row.TEMPO_CANCELAMENTO_MIN);

  if (!timezone || !Number.isFinite(tempoCancelamentoMinutos) || tempoCancelamentoMinutos < 0) {
    existeInvalido = true;
    continue;
  }

  empresaReal = {
    nome,
    telefone,
    email,
    timezone,
    tempoCancelamentoMinutos,
    whatsappConfigurado: campoPresente(row.WHATSAPP_PHONE_NUMBER_ID),
  };
}

if (quantidadeLinhasReais > 1) {
  // Duplicidade acidental na fonte para o mesmo ID_EMPRESA — nunca escolher uma linha
  // silenciosamente nem mesclar dados. Falha determinística e genérica.
  return erroUpstream();
}

if (existeInvalido) {
  return erroUpstream();
}

if (!empresaReal) {
  return erroUpstream();
}

return [{ json: { empresa: empresaReal, requestId } }];

// DISPONIBILIDADES: schema real confirmado (correção de schema desta tarefa — a
// conclusão anterior de 8 colunas, baseada só no subconjunto lido por AGE-WF004, estava
// incompleta) — 10 colunas: ID_DISPONIBILIDADE, ID_EMPRESA, ID_PROFISSIONAL,
// DIA_SEMANA_NUM (convenção do cadastro: 0=domingo..6=sábado, distinta do weekday do
// Luxon — comentário do próprio AGE-WF004), DIA_SEMANA (texto), HORA_INICIO, HORA_FIM,
// INTERVALO_INICIO, INTERVALO_FIM (opcionais), ATIVO ('SIM'/'NAO'). Nunca inclui
// ID_EMPRESA na saída.
//
// ID_DISPONIBILIDADE e DIA_SEMANA (texto) NÃO fazem parte do shape de saída: o contrato
// público não tem campo equivalente a ID_DISPONIBILIDADE (identificador interno de
// linha), e `diaSemana` (string) do contrato já é DERIVADO de DIA_SEMANA_NUM em
// configuracoes.service.ts — expor DIA_SEMANA bruto criaria uma segunda fonte de
// verdade para o mesmo conceito, sem necessidade (o vocabulário textual real de
// DIA_SEMANA não está confirmado, então não há como validar consistência entre as duas
// colunas sem risco de inventar valores). As duas PARTICIPAM, porém, da distinção
// placeholder x linha corrompida abaixo.
//
// `disponibilidades.listar` NÃO replica o filtro adicional `ATIVO='SIM'` que AGE-WF004
// usa (ele só quer dias abertos para calcular horários livres) — aqui vêm TODOS os dias,
// abertos e fechados, para montar a grade completa por profissional no contrato público
// (a tradução DIA_SEMANA_NUM -> enum de string e o preenchimento dos dias sem linha real
// acontecem em configuracoes.service.ts, não aqui).
//
// Hardening (mesmo padrão de Serviços/Profissionais): ID_PROFISSIONAL, DIA_SEMANA_NUM e
// ATIVO são obrigatórios. DIA_SEMANA_NUM só aceita um inteiro 0-6 — qualquer outro valor
// falha a operação inteira. ATIVO só aceita exatamente 'SIM'/'NAO' (trim+uppercase,
// nunca default). Quando ATIVO='SIM', HORA_INICIO/HORA_FIM também são obrigatórios (um
// dia aberto sem horário é dado corrompido); quando ATIVO='NAO', ficam null (nunca
// fabricados, mesmo que a planilha tenha valores residuais nessas colunas — um dia
// fechado não tem horário válido, independente do que sobrou na linha).
// INTERVALO_INICIO/INTERVALO_FIM são sempre opcionais.
//
// Placeholder x linha corrompida (revisado nesta correção para incluir
// ID_DISPONIBILIDADE e DIA_SEMANA): item sem NENHUM campo real presente
// (ID_DISPONIBILIDADE/DIA_SEMANA_NUM/DIA_SEMANA/ATIVO/HORA_INICIO/HORA_FIM/
// INTERVALO_INICIO/INTERVALO_FIM também ausentes) é o placeholder legítimo do
// alwaysOutputData — busca realmente vazia. Uma linha real com QUALQUER um desses
// campos preenchido mas ID_PROFISSIONAL ausente é dado corrompido, nunca "nenhuma
// disponibilidade" (isso vale explicitamente para ID_DISPONIBILIDADE preenchido sem
// ID_PROFISSIONAL, e para DIA_SEMANA preenchido sem ID_PROFISSIONAL). Um valor 0 válido
// (ex.: DIA_SEMANA_NUM=0, domingo) conta como presente, nunca como ausência.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function textoOuNull(valor) {
  if (!campoPresente(valor)) return null;
  const texto = typeof valor === 'string' ? valor : String(valor);
  const aparado = texto.trim();
  return aparado ? aparado : null;
}

let existeInvalido = false;
const disponibilidades = [];

for (const row of linhas) {
  if (!row) continue;

  const temIdProfissional = campoPresente(row.ID_PROFISSIONAL);
  const temOutroCampo =
    campoPresente(row.ID_DISPONIBILIDADE) ||
    campoPresente(row.DIA_SEMANA_NUM) ||
    campoPresente(row.DIA_SEMANA) ||
    campoPresente(row.ATIVO) ||
    campoPresente(row.HORA_INICIO) ||
    campoPresente(row.HORA_FIM) ||
    campoPresente(row.INTERVALO_INICIO) ||
    campoPresente(row.INTERVALO_FIM);

  if (!temIdProfissional && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente vazia — não é erro, não
    // é uma disponibilidade. Ignorado.
    continue;
  }

  if (!temIdProfissional) {
    // Linha real (tem algum campo operacional preenchido, incluindo ID_DISPONIBILIDADE
    // ou DIA_SEMANA sozinhos) mas sem ID_PROFISSIONAL — dado corrompido da fonte, nunca
    // "nenhuma disponibilidade".
    existeInvalido = true;
    continue;
  }

  const diaSemanaNum = Number(row.DIA_SEMANA_NUM);
  const ativoTexto = typeof row.ATIVO === 'string' ? row.ATIVO.trim().toUpperCase() : '';

  if (!Number.isInteger(diaSemanaNum) || diaSemanaNum < 0 || diaSemanaNum > 6) {
    existeInvalido = true;
    continue;
  }
  if (ativoTexto !== 'SIM' && ativoTexto !== 'NAO') {
    existeInvalido = true;
    continue;
  }

  const aberto = ativoTexto === 'SIM';
  const horaInicio = textoOuNull(row.HORA_INICIO);
  const horaFim = textoOuNull(row.HORA_FIM);

  if (aberto && (!horaInicio || !horaFim)) {
    existeInvalido = true;
    continue;
  }

  disponibilidades.push({
    idProfissional: String(row.ID_PROFISSIONAL),
    diaSemanaNum,
    aberto,
    horaInicio: aberto ? horaInicio : null,
    horaFim: aberto ? horaFim : null,
    intervaloInicio: textoOuNull(row.INTERVALO_INICIO),
    intervaloFim: textoOuNull(row.INTERVALO_FIM),
  });
}

if (existeInvalido) {
  // Mensagem genérica de propósito — nunca expõe qual linha/ID_PROFISSIONAL/ID_EMPRESA/
  // planilha está com o dado inválido.
  return [{ json: {
    erro_codigo: 'UPSTREAM_ERROR',
    erro_mensagem: 'Uma ou mais disponibilidades cadastradas possuem dados inválidos.',
    requestId,
  } }];
}

return [{ json: { disponibilidades, requestId } }];

// AGENDAMENTOS: schema real confirmado — ID_AGENDAMENTO, ID_EMPRESA, ID_CLIENTE,
// ID_PROFISSIONAL, ID_SERVICO, DATA, HORA_INICIO, HORA_FIM, DURACAO_MIN, VALOR, STATUS,
// ORIGEM, OBSERVACOES, GOOGLE_EVENT_ID, DATA_CRIACAO, ULTIMA_ATUALIZACAO,
// DATA_CANCELAMENTO, MOTIVO_CANCELAMENTO. Nunca inclui ID_EMPRESA nem colunas técnicas
// na saída (DURACAO_MIN, ORIGEM, OBSERVACOES, GOOGLE_EVENT_ID, DATA_CRIACAO,
// ULTIMA_ATUALIZACAO, DATA_CANCELAMENTO, MOTIVO_CANCELAMENTO) — nenhuma tem necessidade
// legítima demonstrada nesta operação. Nomes de cliente/profissional/serviço também NÃO
// são resolvidos aqui — só os IDs; a composição/join fica inteiramente no NestJS
// (agenda.service.ts, via Promise.all com Clientes/Profissionais/Serviços), mesmo
// princípio de minimização de dados já usado nas demais operações deste gateway.
//
// STATUS: a fonte real sustenta 'AGENDADO'/'CONCLUIDO'/'CANCELADO' — corrigido na
// homologação contra BEAUTYFLOW_HOMOLOGACAO (achado real: linha AGE_TESTE_WF015_04
// com STATUS=CONCLUIDO), que revelou incompleta a premissa anterior de que só
// AGENDADO/CANCELADO existiam. 'PENDENTE'/'CONFIRMADO' continuam NUNCA aceitos
// (conceitos do contrato público do App sem persistência real, ver migração do
// modelo de status da Agenda) — CONCLUIDO é reconhecido só porque a própria fonte o
// grava literalmente, nunca inferido por data/hora/pagamento. Qualquer STATUS fora
// desta whitelist de 3 valores falha a operação INTEIRA; nunca inventa um
// mapeamento (ex.: AGENDADO -> PENDENTE) que a fonte não sustenta.
// `statusConfirmacao` não é produzido aqui: o NestJS sempre acrescenta `null` ao
// converter este shape de integração para o contrato público — para os 3 valores de
// STATUS, incluindo CONCLUIDO —, nunca fabricado pelo workflow.
//
// dataInicio/dataFim: já validados pelo DTO do NestJS (AgendaQuery), mas o workflow
// nunca confia cegamente nisso — revalida aqui só formato/presença (checagem técnica,
// não regra de negócio). O filtro de ID_EMPRESA já aconteceu em `GS - Buscar
// Agendamentos` (tenant isolation na fonte, não só no NestJS); dataInicio/dataFim são
// aplicados aqui porque o node Google Sheets só suporta lookup de igualdade, não
// intervalo. Importante: TODAS as linhas reais da empresa (de qualquer período) são
// validadas antes do corte por período — uma linha corrompida fora do intervalo pedido
// nunca escapa silenciosamente da checagem.
//
// Placeholder x linha corrompida (mesmo padrão de Serviços/Profissionais/
// Disponibilidades/Empresa): item sem NENHUM campo operacional presente é o placeholder
// legítimo do alwaysOutputData — busca realmente vazia. Uma linha real com QUALQUER
// campo preenchido mas ID_AGENDAMENTO ausente é dado corrompido, nunca "nenhum
// agendamento". Uma linha com ID_AGENDAMENTO presente mas faltando qualquer um dos
// demais campos obrigatórios (ID_CLIENTE/ID_PROFISSIONAL/ID_SERVICO/DATA/HORA_INICIO/
// HORA_FIM/VALOR/STATUS) também é inválida — a operação nunca devolve lista parcial.
const contexto = $('CODE - Validar Envelope').first().json;
const requestId = contexto.requestId;
const dadosRequisicao = (contexto.dados && typeof contexto.dados === 'object') ? contexto.dados : {};
const linhas = $input.all().map((item) => item.json);

const DATA_REGEX = /^\d{4}-\d{2}-\d{2}/;
const HORA_REGEX = /^\d{2}:\d{2}/;
const STATUS_VALIDOS = new Set(['AGENDADO', 'CONCLUIDO', 'CANCELADO']);

function erro(codigo, mensagem) {
  return [{ json: { erro_codigo: codigo, erro_mensagem: mensagem, requestId } }];
}

const dataInicio = typeof dadosRequisicao.dataInicio === 'string' ? dadosRequisicao.dataInicio.trim() : '';
const dataFim = typeof dadosRequisicao.dataFim === 'string' ? dadosRequisicao.dataFim.trim() : '';

if (!DATA_REGEX.test(dataInicio) || !DATA_REGEX.test(dataFim)) {
  return erro('VALIDATION_ERROR', 'dataInicio/dataFim são obrigatórios e devem estar no formato YYYY-MM-DD.');
}

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function normalizarValorMonetario(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor == null ? '' : valor).trim().replace(/^R\$\s*/i, '');
  if (texto.includes('.') && texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }
  return Number(texto);
}

let existeInvalido = false;
const todasReais = [];

for (const row of linhas) {
  if (!row) continue;

  const temIdAgendamento = campoPresente(row.ID_AGENDAMENTO);
  const temOutroCampo =
    campoPresente(row.ID_CLIENTE) ||
    campoPresente(row.ID_PROFISSIONAL) ||
    campoPresente(row.ID_SERVICO) ||
    campoPresente(row.DATA) ||
    campoPresente(row.HORA_INICIO) ||
    campoPresente(row.HORA_FIM) ||
    campoPresente(row.DURACAO_MIN) ||
    campoPresente(row.VALOR) ||
    campoPresente(row.STATUS) ||
    campoPresente(row.ORIGEM) ||
    campoPresente(row.OBSERVACOES) ||
    campoPresente(row.GOOGLE_EVENT_ID) ||
    campoPresente(row.DATA_CRIACAO) ||
    campoPresente(row.ULTIMA_ATUALIZACAO) ||
    campoPresente(row.DATA_CANCELAMENTO) ||
    campoPresente(row.MOTIVO_CANCELAMENTO);

  if (!temIdAgendamento && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente vazia — não é erro, não
    // é um agendamento. Ignorado.
    continue;
  }

  if (!temIdAgendamento) {
    // Linha real (tem algum campo operacional preenchido) mas sem ID_AGENDAMENTO —
    // dado corrompido da fonte, nunca "nenhum agendamento".
    existeInvalido = true;
    continue;
  }

  if (
    !campoPresente(row.ID_CLIENTE) ||
    !campoPresente(row.ID_PROFISSIONAL) ||
    !campoPresente(row.ID_SERVICO) ||
    !campoPresente(row.DATA) ||
    !campoPresente(row.HORA_INICIO) ||
    !campoPresente(row.HORA_FIM) ||
    !campoPresente(row.VALOR) ||
    !campoPresente(row.STATUS)
  ) {
    // ID_AGENDAMENTO presente mas alguma referência/campo obrigatório ausente — dado
    // inválido, nunca completado com um valor fabricado.
    existeInvalido = true;
    continue;
  }

  const dataBruta = String(row.DATA).trim();
  const data = DATA_REGEX.test(dataBruta) ? dataBruta.slice(0, 10) : '';
  const horaInicioBruta = String(row.HORA_INICIO).trim();
  const horaInicio = HORA_REGEX.test(horaInicioBruta) ? horaInicioBruta.slice(0, 5) : '';
  const horaFimBruta = String(row.HORA_FIM).trim();
  const horaFim = HORA_REGEX.test(horaFimBruta) ? horaFimBruta.slice(0, 5) : '';
  const valor = normalizarValorMonetario(row.VALOR);
  const status = typeof row.STATUS === 'string' ? row.STATUS.trim().toUpperCase() : '';

  if (
    !data ||
    !horaInicio ||
    !horaFim ||
    !Number.isFinite(valor) ||
    valor < 0 ||
    !STATUS_VALIDOS.has(status)
  ) {
    existeInvalido = true;
    continue;
  }

  todasReais.push({
    idAgendamento: String(row.ID_AGENDAMENTO),
    idCliente: String(row.ID_CLIENTE),
    idProfissional: String(row.ID_PROFISSIONAL),
    idServico: String(row.ID_SERVICO),
    data,
    horaInicio,
    horaFim,
    valor,
    status,
  });
}

if (existeInvalido) {
  // Mensagem genérica de propósito — nunca expõe qual linha/ID_AGENDAMENTO/ID_EMPRESA/
  // planilha está com o dado inválido.
  return erro('UPSTREAM_ERROR', 'Um ou mais agendamentos cadastrados possuem dados inválidos.');
}

// Corte por período aplicado só depois de validar TODAS as linhas reais da empresa —
// ver comentário do topo: uma linha corrompida fora do intervalo pedido não escapa
// silenciosamente da checagem acima.
const agendamentos = todasReais.filter((item) => item.data >= dataInicio && item.data <= dataFim);

return [{ json: { agendamentos, requestId } }];
